use crate::{managed_vault_linked_import::*,db::Db,managed_vault::{self,Store,Manifest},managed_vault_transfer as transfer};
use serde_json::{json,Value};use std::{collections::BTreeMap,path::PathBuf};
struct F{root:PathBuf,db:Db,store:Store,target:String}
impl Drop for F{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.root);}}
fn fixture()->F{
 let root=std::env::temp_dir().join(format!("transfer-review-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&root).unwrap();let mut db=Db::open(&root.join("luckyray-mobile.db")).unwrap();
 db.content_vault_remember("desktop-a","vault-a","A").unwrap();
 db.content_apply_batch("desktop-a","vault-a",&[json!({"noteId":"server","vaultId":"vault-a","title":"Server","content":"server","relativePath":"Server.md","revision":"r1","resources":[],"deleted":false})],1,None).unwrap();
 let store=Store::new(&root).unwrap();store.commit(Manifest{version:1,local_vault_id:"local".into(),name:"Local".into(),binding:None,checkpoint:Value::Null,generation:0,notes:BTreeMap::new(),folders:vec![]},BTreeMap::new()).unwrap();store.register("local").unwrap();
 {let _g=managed_vault::lock().unwrap();db.managed_migrate_replicas().unwrap();}
 let target=store.list().unwrap()["items"].as_array().unwrap().iter().find(|x|x["binding"].is_object()).unwrap()["localVaultId"].as_str().unwrap().to_owned();F{root,db,store,target}
}

fn prepare(f:&F)->State {let p=transfer::preview(&f.db,&f.store,"local",&f.target).unwrap();begin(&f.db,&f.store,"local",&f.target,p["snapshotHash"].as_str().unwrap()).unwrap().unwrap()}
fn reserved(s:&State)->Value {let items=s.entries.iter().zip(&s.snapshot.notes).map(|(e,n)|crate::managed_vault_wiki_plan::ReservedPath{source_note_id:e.source_note_id.clone(),note_id:e.note_id.clone(),relative_path:if n.folder.is_empty(){format!("{}.md",n.title)}else{format!("{}/{}.md",n.folder,n.title)}}).collect::<Vec<_>>();json!({"version":1,"planId":"ip-test","vaultId":"vault-a","sourceFingerprint":s.snapshot.snapshot_hash,"mappingHash":mapping_hash("vault-a",&s.snapshot.snapshot_hash,&items),"state":"prepared","items":items.iter().map(|i|json!({"sourceNoteId":i.source_note_id,"noteId":i.note_id,"relativePath":i.relative_path})).collect::<Vec<_>>()})}
#[test]fn linked_cycle_uses_only_planned_ops_and_redirects_after_receipts(){let mut f=fixture();f.store.create("local","A","[[B]]",vec![],"").unwrap();f.store.create("local","B","[[A]]",vec![],"").unwrap();let p=prepare(&f);let r=reserved(&p);accept_and_adopt(&f.db,&f.store,p.clone(),&r).unwrap();let ops=f.db.content_prepare_operations("desktop-a","vault-a").unwrap();assert_eq!(ops.len(),2);let prepared=f.db.content_prepare_available_operations("desktop-a","vault-a",Some(false)).unwrap();assert_eq!(prepared.len(),2);for op in prepared{assert_eq!(op.route,crate::db::content_db::NoteOperationRoute::KnowledgeImportPlanned);let d=json!({"noteId":op.payload["noteId"],"vaultId":"vault-a","revision":"r1","title":op.payload["title"],"relativePath":op.payload["importPlan"]["relativePath"],"content":op.payload["content"],"resources":[]});assert!(d["content"].as_str().unwrap().contains(".md"));f.db.content_ack("desktop-a","vault-a",op.payload["noteId"].as_str().unwrap(),op.payload["opId"].as_str().unwrap(),&d).unwrap();}f.db.managed_recover().unwrap();assert_eq!(f.store.manifest("local").unwrap().checkpoint["transfer"]["state"],"completed");assert!(f.store.get("local",&p.entries[0].source_note_id).unwrap().remote["transferredTo"].is_object());let repeat=begin(&f.db,&f.store,"local",&f.target,&p.snapshot.snapshot_hash).unwrap().unwrap();accept_and_adopt(&f.db,&f.store,repeat,&r).unwrap();assert_eq!(f.store.manifest(&f.target).unwrap().notes.len(),3);}
#[test]fn reservation_does_not_freeze_source_and_changed_source_fails_adoption(){let f=fixture();let n=f.store.create("local","A","[[A]]",vec![],"").unwrap();let p=prepare(&f);f.store.save("local",&n.note_id,&n.revision,"A","changed",vec![]).unwrap();assert!(accept_and_adopt(&f.db,&f.store,p.clone(),&reserved(&p)).is_err());assert_eq!(f.store.manifest(&f.target).unwrap().notes.len(),1);assert!(f.store.manifest("local").unwrap().checkpoint["transfer"].is_null());}
#[test]fn unknown_ref_and_mapping_corruption_never_freeze_or_adopt(){let f=fixture();f.store.create("local","A","[[Missing]]",vec![],"").unwrap();let p=prepare(&f);let mut r=reserved(&p);r["mappingHash"]=json!("bad");assert!(accept_and_adopt(&f.db,&f.store,p.clone(),&r).is_err());assert!(accept_and_adopt(&f.db,&f.store,p.clone(),&reserved(&p)).is_err());assert_eq!(f.store.manifest(&f.target).unwrap().notes.len(),1);assert!(f.store.manifest("local").unwrap().checkpoint["transfer"].is_null());}
#[test]fn hash_matches_desktop_fixture(){use crate::managed_vault_wiki_plan::ReservedPath as R;assert_eq!(mapping_hash("vault",&"a".repeat(64),&[R{source_note_id:"a".into(),note_id:"kn-a".into(),relative_path:"A.md".into()},R{source_note_id:"b".into(),note_id:"kn-b".into(),relative_path:"B.md".into()}]),"380274e09666b66def4ef5126777c8e3c39cc57a2cb8731000428830b23e3049");}

#[test]fn stale_unadopted_plan_refresh_retains_old_ids_as_archive(){let f=fixture();let n=f.store.create("local","A","[[A]]",vec![],"").unwrap();let old=prepare(&f);f.store.save("local",&n.note_id,&n.revision,"A","changed [[A]]",vec![]).unwrap();let fresh=prepare(&f);assert_ne!(fresh.prepare_op_id,old.prepare_op_id);assert_ne!(fresh.entries[0].note_id,old.entries[0].note_id);assert!(f.store.vault_root("local").unwrap().join(format!(".luckyray/linked-import-abandoned-{}.json",old.prepare_op_id)).exists());accept_and_adopt(&f.db,&f.store,fresh.clone(),&reserved(&fresh)).unwrap();assert!(f.store.manifest("local").unwrap().checkpoint["transfer"].is_object());}
#[test]fn planned_late_ack_preserves_newer_body_and_exact_original_operation(){let mut f=fixture();f.store.create("local","A","[[A]]",vec![],"").unwrap();let p=prepare(&f);accept_and_adopt(&f.db,&f.store,p.clone(),&reserved(&p)).unwrap();let op=f.db.content_prepare_available_operations("desktop-a","vault-a",Some(true)).unwrap().pop().unwrap();let id=op.payload["noteId"].as_str().unwrap();let epoch=f.db.content_begin_edit("desktop-a","vault-a",id).unwrap()["editorEpoch"].as_i64().unwrap();f.db.content_edit("desktop-a","vault-a",id,"A","newer local body",epoch,1).unwrap();let retry=f.db.content_prepare_available_operations("desktop-a","vault-a",Some(false)).unwrap().pop().unwrap();assert_eq!(retry.payload,op.payload);assert_eq!(retry.route,op.route);let d=json!({"noteId":id,"vaultId":"vault-a","revision":"r1","title":"A","relativePath":op.payload["importPlan"]["relativePath"],"content":op.payload["content"],"resources":[]});f.db.content_ack("desktop-a","vault-a",id,op.payload["opId"].as_str().unwrap(),&d).unwrap();let after=f.db.content_note("desktop-a","vault-a",id).unwrap();assert_eq!(after["content"],"newer local body");assert_eq!(after["dirty"],true);let next=f.db.content_prepare_available_operations("desktop-a","vault-a",Some(true)).unwrap().pop().unwrap();assert_eq!(next.route,crate::db::content_db::NoteOperationRoute::Content);assert_eq!(next.payload["expectedRevision"],"r1");}
#[test]fn blocked_planned_entry_does_not_starve_unrelated_upload(){let mut f=fixture();f.store.create("local","A","[[A]]",vec![],"").unwrap();let p=prepare(&f);accept_and_adopt(&f.db,&f.store,p.clone(),&reserved(&p)).unwrap();f.db.managed_linked_block("desktop-a","vault-a",&p.entries[0].note_id).unwrap();f.db.content_create("desktop-a","vault-a","unrelated","Other","safe").unwrap();let pending=f.db.content_prepare_available_operations("desktop-a","vault-a",Some(false)).unwrap();assert_eq!(pending.len(),1);assert_eq!(pending[0].payload["noteId"],"unrelated");assert!(f.db.content_sync_attention("desktop-a","vault-a").unwrap());assert!(f.store.get("local",&p.entries[0].source_note_id).unwrap().remote["transferredTo"].is_null());}
#[test]fn oversized_source_fails_before_freeze_or_target_changes(){for linked in [false,true]{let f=fixture();let body=format!("{}{}","x".repeat(4*1024*1024),if linked{"[[A]]"}else{"x"});f.store.create("local","A",&body,vec![],"").unwrap();let p=transfer::preview(&f.db,&f.store,"local",&f.target).unwrap();assert_eq!(p["canCommit"],false);let hash=p["snapshotHash"].as_str().unwrap();if linked{assert!(begin(&f.db,&f.store,"local",&f.target,hash).is_err())}else{assert!(transfer::commit(&f.db,&f.store,"local",&f.target,hash).is_err())}assert!(f.store.manifest("local").unwrap().checkpoint["transfer"].is_null());assert_eq!(f.store.manifest(&f.target).unwrap().notes.len(),1);}}
#[test]fn ast_proofs_are_durable_and_enable_bullets_without_rewriting_code(){let f=fixture();let n=f.store.create("local","A","- [[A]]\n`[[Missing]]`",vec![],"").unwrap();let p=prepare(&f);let proofs=json!([{"sourceNoteId":n.note_id,"sourceSha256":managed_vault::hash(n.content.as_ref().unwrap().as_bytes()),"spans":[{"startByte":2,"endByte":7,"token":"[[A]]"}],"resourceIssues":[]}]);let p=attach_proofs(&f.store,p,Some(proofs.clone())).unwrap();assert_eq!(load(&f.store,"local").unwrap().unwrap().wiki_proofs,Some(proofs));accept_and_adopt(&f.db,&f.store,p.clone(),&reserved(&p)).unwrap();assert_eq!(f.store.get(&f.target,&p.entries[0].note_id).unwrap().content.as_deref(),Some("- [[./A.md]]\n`[[Missing]]`"));}
#[test]fn schema15_preserves_old_operation_and_pause_bytes(){let root=std::env::temp_dir().join(format!("linked-schema-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&root).unwrap();let path=root.join("db");drop(Db::open(&path).unwrap());let c=rusqlite::Connection::open(&path).unwrap();let raw="{ \"opId\" : \"old\", \"kind\":\"rename\" }";c.execute("INSERT INTO content_note_operation VALUES('i','v','n','old',?1,17,'content')",[raw]).unwrap();c.execute("INSERT INTO content_note_operation_pause VALUES('i','v','n','old',?1,'content',17,'BLANK_RENAME_400','time')",[raw]).unwrap();c.execute_batch("PRAGMA user_version=14").unwrap();drop(c);drop(Db::open(&path).unwrap());let c=rusqlite::Connection::open(&path).unwrap();let row:(String,String,i64,String)=c.query_row("SELECT op_id,payload,draft_generation,route FROM content_note_operation",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?))).unwrap();assert_eq!(row,("old".into(),raw.into(),17,"content".into()));assert_eq!(c.query_row("SELECT payload FROM content_note_operation_pause",[],|r|r.get::<_,String>(0)).unwrap(),raw);assert!(c.execute("UPDATE content_note_operation_pause SET payload='changed'",[]).is_err());assert_eq!(c.query_row("PRAGMA user_version",[],|r|r.get::<_,i64>(0)).unwrap(),15);drop(c);std::fs::remove_dir_all(root).unwrap();}
#[test]fn source_folder_changed_during_reservation_rejects_without_freezing(){let f=fixture();f.store.create("local","A","[[A]]",vec![],"").unwrap();let p=prepare(&f);f.store.folder_create("local","Later","").unwrap();assert_eq!(accept_and_adopt(&f.db,&f.store,p.clone(),&reserved(&p)).unwrap_err(),"VAULT_TRANSFER_SOURCE_CHANGED");assert!(f.store.manifest("local").unwrap().checkpoint["transfer"].is_null());assert_eq!(f.store.manifest(&f.target).unwrap().notes.len(),1);}
#[test]fn malformed_proofs_leave_preparation_retryable(){let f=fixture();f.store.create("local","A","[[A]]",vec![],"").unwrap();let p=prepare(&f);assert!(attach_proofs(&f.store,p.clone(),Some(json!([]))).is_err());assert!(load(&f.store,"local").unwrap().unwrap().wiki_proofs.is_none());accept_and_adopt(&f.db,&f.store,p.clone(),&reserved(&p)).unwrap();}
#[test]fn invalid_title_preflight_keeps_original_editable(){let f=fixture();let n=f.store.create("local",&"长".repeat(81),"[[A]]",vec![],"").unwrap();let p=transfer::preview(&f.db,&f.store,"local",&f.target).unwrap();assert_eq!(p["blockedCount"],1);assert_eq!(p["canCommit"],false);assert!(begin(&f.db,&f.store,"local",&f.target,p["snapshotHash"].as_str().unwrap()).is_err());assert!(f.store.manifest("local").unwrap().checkpoint["transfer"].is_null());assert!(f.store.save("local",&n.note_id,&n.revision,"A","[[A]]",vec![]).is_ok());}

#[test]fn planned_entry_waits_for_immutable_folder_receipt(){let mut f=fixture();f.store.folder_create("local","F","").unwrap();f.store.create("local","A","[[F/A]]",vec![],"F").unwrap();let p=prepare(&f);accept_and_adopt(&f.db,&f.store,p.clone(),&reserved(&p)).unwrap();assert!(f.db.content_prepare_available_operations("desktop-a","vault-a",Some(true)).unwrap().is_empty());let folders=f.db.managed_pending_folders("desktop-a","vault-a").unwrap();assert_eq!(folders.len(),1);for op in folders{f.db.managed_folder_ack(&op,&json!({"opId":op.op_id,"vaultId":"vault-a","relativePath":op.relative_path,"created":true})).unwrap();}let operations=f.db.content_prepare_available_operations("desktop-a","vault-a",Some(true)).unwrap();assert_eq!(operations.len(),1);assert_eq!(operations[0].route,crate::db::content_db::NoteOperationRoute::KnowledgeImportPlanned);assert_eq!(operations[0].payload["importPlan"]["relativePath"],"F/A.md");}

#[test]fn uppercase_markdown_reservation_and_ack_preserve_exact_path(){let mut f=fixture();f.store.create("local","A.MD","[[A.MD]]",vec![],"").unwrap();let p=prepare(&f);let paths=vec![crate::managed_vault_wiki_plan::ReservedPath{source_note_id:p.entries[0].source_note_id.clone(),note_id:p.entries[0].note_id.clone(),relative_path:"A.MD".into()}];let mut r=reserved(&p);r["items"][0]["relativePath"]=json!("A.MD");r["mappingHash"]=json!(mapping_hash("vault-a",&p.snapshot.snapshot_hash,&paths));accept_and_adopt(&f.db,&f.store,p.clone(),&r).unwrap();let op=f.db.content_prepare_available_operations("desktop-a","vault-a",Some(true)).unwrap().pop().unwrap();let d=json!({"noteId":op.payload["noteId"],"vaultId":"vault-a","revision":"r1","title":"A","relativePath":"A.MD","content":op.payload["content"],"resources":[]});f.db.content_ack("desktop-a","vault-a",op.payload["noteId"].as_str().unwrap(),op.payload["opId"].as_str().unwrap(),&d).unwrap();assert_eq!(f.store.get(&f.target,&p.entries[0].note_id).unwrap().remote["relativePath"],"A.MD");}
#[test]fn ack_title_uses_desktop_path_stem_semantics_for_dotfile(){let p=json!({"opId":"op","noteId":"kn-a","vaultId":"v","kind":"create","content":"body","importPlan":{"version":1,"planId":"ip-test","mappingHash":"a".repeat(64),"relativePath":".MD","contentSha256":managed_vault::hash(b"body")}});let d=json!({"noteId":"kn-a","vaultId":"v","revision":"r1","title":".MD","relativePath":".MD","content":"body","resources":[]});assert!(validate_document(&p,&d).is_ok());}
